/* zanac_banks.h - the assembled PRG banks of Zanac (USA) as C arrays.
 *
 * GENERATED by c_src/tools/gen_zanac.py from Build/bankN.bin.
 * Banks 0-3 are empty, bank 4 holds graphics data, bank 5 level data and
 * banks 6/7 code plus the data tables the ported code reads through the
 * bank window.  The C port reads these arrays instead of emulating the
 * UxROM mapper: switching a bank is just changing the index used by
 * zanac_bank_read().
 */
#ifndef ZANAC_BANKS_H
#define ZANAC_BANKS_H

#include <stdint.h>

#define ZANAC_BANK_SIZE  16384u
#define ZANAC_BANK_COUNT 8

extern const uint8_t zanac_bank_empty[ZANAC_BANK_SIZE];
extern const uint8_t zanac_bank4[ZANAC_BANK_SIZE];
extern const uint8_t zanac_bank5[ZANAC_BANK_SIZE];
extern const uint8_t zanac_bank6[ZANAC_BANK_SIZE];
extern const uint8_t zanac_bank7[ZANAC_BANK_SIZE];

/* All banks, indexed by the value written to the bank register. */
extern const uint8_t *const zanac_banks[ZANAC_BANK_COUNT];

#endif /* ZANAC_BANKS_H */
